"""results.json -> REPORT.md (generated; no hand-typed numbers)."""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__)); S = json.load(open(os.path.join(HERE, "results.json")))
L = ["# CCL on real decisions: one US mortgage lender, HMDA 2018-2023 (auto-generated by report.py)", "",
     f"Lender: U.S. Bank National Association (public LEI {S['lender']}); conventional, first-lien, owner-occupied home-purchase applications, originated vs denied.",
     "Statute = the written Qualified Mortgage DTI cap (approve iff DTI <= 43%). Yearly replay: mine on t-3..t-2, admit on t-1, test on t.",
     "Race / ethnicity / sex / age are never mined; they are used only for the disparate-impact audit. HMDA has no outcomes and no credit scores.", "",
     "| year | decisions | approval rate | residual vs policy |", "|---|---|---|---|"]
for y in S["rows"]: L.append(f"| {y} | {S['rows'][y]} | {S['approval_rate'][y]:.3f} | {S['residual_rate'][y]:.3f} |")
L += ["", "## Accuracy on the held-out year", "", "| test year | written policy | always approve | CCL (beam) | CCL (power-aware) | black box (GBM) |", "|---|---|---|---|---|---|"]
for t, r in S["tests"].items():
    L.append(f"| {t} | {r['statute']['acc']:.3f} | {r['always_approve']['acc']:.3f} | {r['beam']['acc']:.3f} | {r['beam_power']['acc']:.3f} | {r['gbm']['acc']:.3f} |")
L += ["", "## Admitted law (power-aware miner), its 'because' (denial reasons) and the fairness audit", "",
      "audit ratio = lowest / highest group rate of the holding's benefit (loosen) or burden (tighten); < 0.8 fails the four-fifths rule.", "",
      "| test year | kind | holding | support | replay precision | because (top denial reasons) | race ratio | sex ratio |", "|---|---|---|---|---|---|---|---|"]
for t, r in S["tests"].items():
    for h in r["beam_power"]["holdings"]:
        a = h["audit"]; flag = lambda x: "" if x is None else (f"**{x}**" if x < 0.8 else f"{x}")
        L.append(f"| {t} | {h['kind']} | `{h['sql']}` | {h['support']} | {h['replay_prec']} | {h['because'] or '-'} | {flag(a.get('race', {}).get('ratio'))} | {flag(a.get('sex', {}).get('ratio'))} |")
L += ["", "Reading notes: `disc` is the DTI variable (named so the miner runs unchanged). `aus` = automated underwriting system (TOTAL = FHA scorecard). `score_model = '8'` = 'other credit scoring model'.",
      "Caveats: one lender; DTI is bucketed below 36% and above 49%; no credit score or outcome in HMDA, so most within-policy denials (credit history) are invisible to any miner; the base rate is high (always-approve ~0.91)."]
open(os.path.join(HERE, "REPORT.md"), "w").write("\n".join(L) + "\n"); print("\n".join(L[:30]))
